-- Generated by model/lib/sql/generate.mjs. L1's load of IMPORT Trade Fees from cells/IMPORT Trade Fees.csv in the folder of input cells, into its empty table.
-- Two rows for one cell add up.
-- @csv cells/IMPORT Trade Fees.csv
INSERT INTO "IMPORT Trade Fees" SELECT coalesce(k0."Customer Group", fpabench_error('cells name a member Customer Group does not have: ' || c."Customer Group")), coalesce(k1."Brand", fpabench_error('cells name a member Brand does not have: ' || c."Brand")), coalesce(k2."Years", fpabench_error('cells name a member Years does not have: ' || c."Years")), coalesce(k3."Months", fpabench_error('cells name a member Months does not have: ' || c."Months")), sum(c.value::DOUBLE PRECISION)
FROM csv c LEFT JOIN "dim Customer Group" k0 ON k0.name = c."Customer Group" LEFT JOIN "dim Brand" k1 ON k1.name = c."Brand" LEFT JOIN "dim Years" k2 ON k2.name = c."Years" LEFT JOIN "dim Months" k3 ON k3.name = c."Months"
GROUP BY 1, 2, 3, 4;
ANALYZE "IMPORT Trade Fees";
